// Generated by tools/make_landmask.py from docs/data/worldmap_2deg.json.
// Natural Earth 110m land polygons (public domain) on a 2.0-degree grid, rows from
// lat 84.0 down to -58.0, columns from lon -180. Used only by the fallback globe.
export const LAND = { step: 2.0, latTop: 84.0, latBot: -58.0, cols: 180, rows: 71, bits: '' };
export function landBits() {
  const s = atob(LAND.bits);
  const a = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i);
  return a;
}
export function isLand(bits, r, c) {
  const i = r * LAND.cols + c;
  return (bits[i >> 3] >> (i & 7)) & 1;
}
